const detail=v=>'<article class="detail" id="'+v.id+'"><div class="detail-head"><h2>'+v.name+'</h2><a href="'+v.path+'/style.json" download>材质包清单 JSON ↓</a></div><div class="map-layout"><label>装饰区域<select class="region" data-id="'+v.id+'"><option value="body">杯身 · 1024 × 2222</option><option value="handle">把手 · 320 × 3119</option><option value="saucer">底碟 · 2172 × 213</option></select></label><label>PBR 通道<select class="channel" data-id="'+v.id+'">'+['baseColor','normal','roughness','metalness','height'].map(k=>'<option>'+k+'</option>').join('')+'</select></label><a class="map-download" href="'+v.path+'/body-baseColor.png" download>下载当前 PNG ↓</a></div><div class="map-frame"><img class="map" src="'+v.path+'/body-baseColor.png" alt="杯身 BaseColor 展开图，保持原始比例"></div><p class="caption">贴图按原始长宽比显示。五个通道使用同一裁切、尺寸与 UV；底碟为四分之一圆周单元，运行时镜像衔接。</p><details><summary>生成要求、完整提示词与实际输出</summary><p>工具：内置 image_gen。竖向母版要求 1:2，横幅要求 6:1。下面列出实际输出；提示词中的数量、比例与无缝要求是目标，不代表逐项精确达标。</p><div class="masters">'+v.masters.map((m,i)=>'<div><a href="'+v.path+'/masters/'+m.part+'.png"><img src="'+v.path+'/masters/'+m.part+'.png" alt="原始生成母版"></a><p>'+m.part+' 原始母版 · '+m.width+' × '+m.height+' px</p><details><summary>完整 '+m.part+' 提示词</summary><pre>'+esc(v.prompts[i])+'</pre></details></div>').join('')+'</div><p>原始提示词从 assets/prompts.json 找回并逐字保留为新提示词前缀，仅追加题材侧重。生成时同时引用原有母版，保持原版花朵尺度、密度与细线风格。新款横幅实际为 3:1；恢复原有规则：底碟取横幅 y=38%～63% 的中间 25%，把手取竖向杯身母版 x=47%～63%、y=7%～89%，再等比覆盖对应展开尺寸。底碟上下金边之间花纹铺满，不留空白横带。</p><p>当前采用色域分割，不是逐瓣人工标注；偏黄花芯、棕色枝干等与金地近色处仍可能被误判。几何比例、镜像重复节奏、微浮雕手感与反射效果需结合实拍继续判断。</p><a href="'+v.path+'/generation.json" download>提示词与输出元数据 JSON ↓</a> · <a href="'+v.path+'/manifest.json" download>裁切、尺寸与 SHA-256 清单 ↓</a></details><details><summary>全部 15 张通道文件</summary><div class="downloads">'+['body','handle','saucer'].map(r=>'<div><h3>'+r+'</h3>'+['baseColor','normal','roughness','metalness','height'].map(c=>'<a href="'+v.path+'/'+r+'-'+c+'.png" download>'+c+' PNG ↓</a>').join('')+'</div>').join('')+'</div></details></article>';
const densityTable='<h3>彩绘覆盖对照（色域遮罩粗估）</h3><div class="table-wrap"><table><thead><tr><th>款式</th><th>杯身</th><th>把手</th><th>底碟</th></tr></thead><tbody>'+variants.map(v=>'<tr><td>'+v.name+'</td>'+['body','handle','saucer'].map(r=>'<td>'+(density.styles[v.id][r].enamelCoverage*100).toFixed(1)+'%</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="fineprint">以现有金地色域遮罩中非金属像素粗估彩绘占比，只辅助检查疏密，不代表逐瓣人工标注或真实金属含量。请同时比较展开图、底碟上下边缘与同机位渲染。</p>';
const css='*{box-sizing:border-box}body{margin:0;background:#f6f3ec;color:#393730;font:15px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}a{color:#75552f;text-underline-offset:4px}header{max-width:1320px;margin:auto;padding:30px 32px 0;display:flex;justify-content:space-between;gap:18px}main{max-width:1320px;margin:auto;padding:34px 32px 70px}h1{font:42px/1.4 "Songti SC",serif;margin:12px 0}h2{font:25px/1.5 "Songti SC",serif;margin:8px 0}h3{font-size:15px}.intro{max-width:760px;color:#686153}.eyebrow{font-size:11px;letter-spacing:2px;color:#8f7754}.locks{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0 32px}.locks span{padding:7px 14px;background:#e9e1d1;border-radius:5px;font-size:13px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{border:1px solid #ded7c8;background:#fffcf6;border-radius:10px;overflow:hidden}.render{background:#b7b8ba;aspect-ratio:1.12;overflow:hidden}.render img{width:100%;height:100%;object-fit:cover}.card-copy{padding:21px}.card-copy p{font-size:13px;color:#797160}.band{width:100%;display:block;margin:18px 0 20px}.button{display:inline-block;text-decoration:none;border:1px solid #baab8e;padding:9px 14px;border-radius:5px;font-size:13px}.standard,.detail{background:#fffcf6;border:1px solid #ded7c8;border-radius:10px;margin-top:30px;padding:28px}.standard p{max-width:950px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;border-bottom:1px solid #e8e1d4;padding:12px 10px}th{color:#8b6b3e}td:first-child{white-space:nowrap}ol{padding-left:24px;color:#665e4f}.detail-head{display:flex;justify-content:space-between;align-items:center;gap:12px}.detail-head a{font-size:12px}.map-layout{display:flex;gap:18px;align-items:end;margin:20px 0;flex-wrap:wrap}label{font-size:12px;color:#80735b}select{display:block;min-width:210px;margin-top:6px;padding:9px;border:1px solid #d1c7b3;border-radius:4px;background:#f4f0e7;color:#403a30}.map-download{font-size:12px;margin-bottom:7px}.map-frame{background:#ebe5d8;border-radius:5px;min-height:240px;display:flex;align-items:center;justify-content:center;padding:18px}.map{max-height:560px;max-width:100%;object-fit:contain;display:block}.caption{font-size:12px;color:#85765d}details{margin-top:16px;border-top:1px solid #e5dece;padding-top:14px}summary{cursor:pointer;color:#725737;font-size:14px}details p{font-size:13px}.masters{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.masters img{max-width:100%;max-height:320px;object-fit:contain}.masters pre{font-size:11px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.downloads{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.downloads a{display:block;font-size:12px}.fineprint{font-size:12px;color:#7d7565}footer{margin-top:30px;font-size:12px;color:#8c7e65}@media(max-width:800px){header{padding:22px 18px 0;font-size:12px}main{padding:22px 18px 40px}h1{font-size:32px}.cards{grid-template-columns:1fr}.render{aspect-ratio:1.2}.standard,.detail{padding:20px}.masters{grid-template-columns:1fr}.detail-head{display:block}.map-layout{display:block}select{width:100%;margin-bottom:12px}.map{max-height:450px}.downloads{grid-template-columns:1fr 1fr}}';
const html='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>花纸与生成标准 · 广彩</title><style>'+css+'</style></head><body><header><a href="./">← 回到三维观察器</a><span>广彩 · 一号杯 / 花纸研究</span></header><main><span class="eyebrow">TEXTURE STUDIES / 2026.09</span><h1>花纸、材质与生成标准</h1><p class="intro">两套新构图与一套原有花纸。下方模型图使用相同器型、机位、亮度与微浮雕强度；可以切换三维款式，也可以直接检查各区展开图和数据通道。</p><div class="locks"><span>彩绘微浮雕固定 <strong>1.5</strong></span><span>摄影棚亮度固定 <strong>1.08</strong></span><span>共 3 款 / 45 张 PBR 贴图</span></div><div class="cards">'+variants.map(card).join('')+'</div><section class="standard"><h2>沿用原版的生成标准</h2><p>本轮使用找回的原始提示词为底稿：<strong>edge to edge、dense、many varied smaller motifs</strong>；横幅保留 <strong>About 14 distinct flower groupings across width</strong>。新款只调整题材侧重，同时恢复原来的三个区域裁切方式。</p><ol><li>用 image_gen 分别生成竖向杯身母版和横向花边母版；保留原图与完整提示词。</li><li>花朵与细线清晰，赭金背景便于分割。目标不包含器皿、文字、摄影高光、阴影和透视。</li><li>杯身按弧带展开；把手按真实外弧长展开；底碟按四分之一圆周展开。沿用原版归一化裁切与等比覆盖，所有通道共用坐标；底碟花叶一直延伸到上下金边。</li><li>一次载入完整材质包；尺寸不一致或图片失败时保留当前款式。切换图案不修改器型、机位或摄影棚亮度。</li></ol>'+densityTable+'<div class="table-wrap"><table><thead><tr><th>装饰区</th><th>展开宽 × 长（mm）</th><th>交付像素</th></tr></thead><tbody><tr><td>杯身弧带</td><td>45.0295 × 97.7000</td><td>1024 × 2222</td></tr><tr><td>把手外弧</td><td>11.9000 × 115.9754</td><td>320 × 3119</td></tr><tr><td>底碟 ¼ 周</td><td>113.4115 × 11.1427</td><td>2172 × 213</td></tr></tbody></table></div><p class="fineprint">展开尺寸来自当前推定模型，只有 151 mm 碟径有产品参数依据。输出像素可能高于母版局部像素，重采样不等于新增真实细节。</p><div class="table-wrap"><table><thead><tr><th>通道</th><th>颜色空间</th><th>处理标准</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="fineprint">1.5 是无量纲的法线强度，不是 1.5 mm。曝光系数 1.08、ACES 色调映射及灯光环境统一；观察角度变化仍会改变金彩反射。PBR 为艺术近似，未通过表面扫描测定。</p></section>'+variants.map(detail).join('')+'<footer>参考风格生成的新稿，非原厂花纸扫描。两套新款最终采用 4 张 AI 原始母版、30 张对齐 PBR PNG；原有款完整保留。所有资产随本地构建交付。</footer></main><script>const catalog='+JSON.stringify(variants.map(({id,path})=>({id,path})))+';function update(id){const root=document.getElementById(id),r=root.querySelector(".region").value,c=root.querySelector(".channel").value,path=catalog.find(v=>v.id===id).path+"/"+r+"-"+c+".png";root.querySelector(".map").src=path;root.querySelector(".map").alt=r+" / "+c+" 原始比例展开图";root.querySelector(".map-download").href=path;}document.querySelectorAll("select").forEach(el=>el.addEventListener("change",()=>update(el.dataset.id)));</script></body></html>';
await writeFile('public/texture-standards.html',html);
console.log('Texture standards: 3 styles, prompts, 45 channel links, full-resolution masters.');

