  {name:'body',input:variant?.masters.body.path??'assets/masters/china-fixed-body.png',width:1024},
  {name:'handle',input:variant?.masters.body.path??'assets/masters/china-fixed-body.png',crop:[.47,.07,.16,.82],width:320},
  {name:'saucer',input:variant?.masters.band.path??'assets/masters/china-fixed-band.png',crop:[0,.38,1,.25],width:2172},
